head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS20801.xml';
scwin.vIsurCd = '', scwin.vMktactCd = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();
scwin.processGp; //등록 1, 수정 2
scwin.btnStat = new Object();
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vIsurCd = scwin.arrPar[0].ISUR_CD;
        if (scwin.arrPar[0].MKTACT_TP_CD != undefined) {
            scwin.vMktactCd = scwin.arrPar[0].MKTACT_TP_CD;
        }
    }
};




/********************************************** 
 * 함수명   : fn_list
 * 설명       : 채권기준명 리스트를 조회한다.
 ***********************************************/
scwin.fn_list = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ISU_BAS_NM";
    url += "&queryId=lds.stf.bnscommon.select.listIsuBasNm";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISUR_CD=" + scwin.vIsurCd;
    url += "&{P}V_POP_YN=" + 'Y';
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명       : 필수 입력값 체크
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(txb_BasIsuNm) == '') {
        $c.win.alert("[한글기준명]을 입력하십시오.");
        txb_BasIsuNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_BasIsuAbbrv) == '') {
        $c.win.alert("[한글기준약명]을 입력하십시오.");
        txb_BasIsuAbbrv.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_BasIsuEngNm) == '') {
        $c.win.alert("[영문기준명]을 입력하십시오.");
        txb_BasIsuEngNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_BasIsuEngAbbrv) == '') {
        $c.win.alert("[영문기준약명]을 입력하십시오.");
        txb_BasIsuEngAbbrv.focus();
        return false;
    }

    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_BasIsuNm, 60, '한글기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuAbbrv, 20, '한글기준약명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuEngNm, 60, '영문기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuEngAbbrv, 20, '영문기준약명')) return false;
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = $c.stf.getObjectValue(txb_BasIsuEngNm);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기준명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngNm.focus();
            return false;
        }
    }
    var str = $c.stf.getObjectValue(txb_BasIsuEngAbbrv);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기준약명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_DuplCheck
 * 설명       : 등록 시, 중복 체크
 ***********************************************/
scwin.fn_DuplCheck = function() {
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if ($c.stf.getObjectValue(txb_BasIsuNm) == dts_List.getCellData(i, "BAS_ISU_NM")) {
            $c.win.alert("동일한 [한글기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuNm.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuAbbrv) == dts_List.getCellData(i, "BAS_ISU_ABBRV")) {
            $c.win.alert("동일한 [한글기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuAbbrv.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuEngNm) == dts_List.getCellData(i, "BAS_ISU_ENG_NM")) {
            $c.win.alert("동일한 [영문기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngNm.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BasIsuEngAbbrv) == dts_List.getCellData(i, "BAS_ISU_ENG_ABBRV")) {
            $c.win.alert("동일한 [영문기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }
};




/********************************************** 
 * 함수명   : fn_InsertMod
 * 설명       : 등록 및 수정을 처리한다.
 ***********************************************/
scwin.fn_InsertMod = function() {
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return;
    var vBfBasIsuNm = dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM");
    var url;
    if (scwin.processGp == '1') {
        //중복체크
        if (scwin.fn_DuplCheck() == false) return;
        if (!confirm("기준명 " + $c.stf.getObjectValue(txb_BasIsuNm) + "(으)로 등록하시겠습니까?")) return;
        url = "/bns/ListBzAppl.do?method=createIsuBas";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&ISUR_CD=" + scwin.vIsurCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetStkIsuNm
 * 설명       : 주권종목명 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetStkIsuNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vIsurCd,
        POP_CALL_YN: 'Y'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetModIsuNm
 * 설명       : 수정 팝업(종목기준명관리)에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetModIsuNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vIsurCd,
        BAS_ISU_NM: $c.stf.getObjectValue(txb_BasIsuNm),
        BAS_ISU_ABBRV: $c.stf.getObjectValue(txb_BasIsuAbbrv),
        BAS_ISU_ENG_NM: $c.stf.getObjectValue(txb_BasIsuEngNm),
        BAS_ISU_ENG_ABBRV: $c.stf.getObjectValue(txb_BasIsuEngAbbrv),
        ISUR_NM: dts_List.getCellData(dts_List.getRowPosition(), "ISUR_NM"),
        POP_CALL: "Y"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetModIsuNm
 * 설명       : 수정 팝업(종목기준명관리)에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetModIsuNm = function(arrPar) {
    if ("Y" == scwin.arrPar[0].MOD_YN) {
        $c.win.alert("수정 처리 성공했습니다.");
        dts_List.Reset();
    }
    if ("Y" == scwin.arrPar[0].DEL_YN) {
        dts_List.Reset();
        scwin.fn_ClearTextField();
    }
};


/******************************************************************* 
 * 함수명   : fn_PopAdminIsurNm
 * 설명     : 채권기준명관리 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopAdminIsurNm = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS20800", "/bnslistbzappl/ULDBNS20800.gfm", "채권기준명 관리", obj_left, obj_top, 1260, 785, "window");
};


/********************************************** 
 * 함수명   : fn_ClearTextField
 * 설명       : 텍스트 필드를 초기화 한다.
 ***********************************************/
scwin.fn_ClearTextField = function() {
    dts_List.setRowPosition(0, 0);
    $c.stf.setObjectValue(txb_BasIsuNm, '');
    $c.stf.setObjectValue(txb_BasIsuAbbrv, '');
    $c.stf.setObjectValue(txb_BasIsuEngNm, '');
    $c.stf.setObjectValue(txb_BasIsuEngAbbrv, '');
};


/*************************************************************************************** 
 * 201,202에서 호출하여 수정 처리 후
 * 화면을 닫을 경우,  콤보박스 리셋 용도 (닫기 버튼이 아닌 X버튼 및 Alt+F4 종료시도 리셋 되어야 하므로)
 ***************************************************************************************/
window.onunload = function() {
    if (scwin.vMktactCd != '' && scwin.processGp == '2') {
        //부모 창 전송 값 설정
        scwin.arrPar[0].SUCCESS_YN = 'Y';
        opener.scwin.fn_SetPar(scwin.arrPar);
    }
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_info);
    //호출파라미터설정
    scwin.fn_SetParam();
    //목록조회
    scwin.fn_list();
    // 가우스헤더 셋팅
    dts_IsuInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_ISU_BAS_NM";
    dts_IsuInfo.reset();
    $c.stf.showObj(lbl_Pop, false); //팝업위치 레이블 숨김

};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    dts_List.setRowPosition(0, 0);
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    scwin.arrPar[0] = {
        BAS_ISU_NM: dts_List.getCellData(row, "BAS_ISU_NM"),
        BAS_ISU_ABBRV: dts_List.getCellData(row, "BAS_ISU_ABBRV"),
        BAS_ISU_ENG_NM: dts_List.getCellData(row, "BAS_ISU_ENG_NM"),
        BAS_ISU_ENG_ABBRV: dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV")
    };
    scwin.fn_SetPar(scwin.arrPar);
    await $c.frame.CloseFrame();
};
scwin.dts_IsuInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_IsuInfo_OnLoadCompleted = function(rowcount) {
    dts_IsuInfo.insertRow();
};
scwin.grd_List_OnClick = function(row, colid) {
    dts_IsuInfo.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_IsuInfo.setCellData(1, "BAS_ISU_NM", dts_List.getCellData(row, "BAS_ISU_NM"));
    dts_IsuInfo.setCellData(1, "BAS_ISU_ABBRV", dts_List.getCellData(row, "BAS_ISU_ABBRV"));
    dts_IsuInfo.setCellData(1, "BAS_ISU_ENG_NM", dts_List.getCellData(row, "BAS_ISU_ENG_NM"));
    dts_IsuInfo.setCellData(1, "BAS_ISU_ENG_ABBRV", dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV"));
};
scwin.btn_Reset_onclick = function() {
    scwin.fn_ClearTextField();
};
scwin.btn_Cfm_onclick = function() {
    scwin.fn_GetPar = fn_GetStkIsuNm;
    $c.bns.fn_PopStkIsuSearch(lbl_Pop);
};
scwin.btn_Insert_onclick = function() {
    scwin.processGp = '1';
    dts_IsuInfo.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    scwin.fn_InsertMod();
};
scwin.btn_Mod_onclick = function() {
    if (dts_List.getTotalRow() == 0) return;
    scwin.processGp = '2';
    scwin.fn_GetPar = fn_GetModIsuNm;
    scwin.fn_SetPar = fn_SetModIsuNm;
    scwin.fn_PopAdminIsurNm(lbl_Pop);
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    }
    dts_List.Reset();

    //201, 202만 호출 시 넘김 (콤보박스 리셋 용도, 닫기 버튼이 아닌 X버튼 및 Alt+F4 종료시도 리셋 되어야 하므로)
    if (scwin.vMktactCd != '') {
        //부모 창 전송 값 설정
        scwin.arrPar[0].SUCCESS_YN = 'Y';
        scwin.fn_SetPar(scwin.arrPar);
    }
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
